import {T,studio,loadVehicle} from './automotive.js';
import {Reflector} from './vendor/three/addons/Reflector.js';
export async function startArrival(){
 const hero=document.querySelector('.hero');if(!hero)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),skip=hero.querySelector('.skip-intro');let seen=false;try{seen=sessionStorage.getItem('martinez-arrival')==='seen'}catch{}
 const stage=document.createElement('div');stage.className='arrival-stage';stage.setAttribute('aria-hidden','true');hero.prepend(stage);const replay=document.createElement('button');replay.className='film-control';replay.textContent='Replay entrance';replay.type='button';replay.hidden=true;hero.append(replay);
 let view;try{view=await studio(stage)}catch{return}const {scene,camera,renderer,floor}=view;scene.fog=new T.Fog('#08090b',22,65);scene.environmentIntensity=.45;renderer.toneMappingExposure=.95;
 const textures=new T.TextureLoader(),map=await textures.loadAsync('/models/concrete.jpg'),normal=await textures.loadAsync('/models/concrete-normal.jpg');for(const texture of [map,normal]){texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(14,14)}map.colorSpace=T.SRGBColorSpace;floor.material=new T.MeshStandardMaterial({map,normalMap:normal,normalScale:new T.Vector2(.4,.4),color:0x252a30,roughness:.36,metalness:.15,envMapIntensity:.15});
 const reflection=new Reflector(new T.PlaneGeometry(90,90),{color:0x15191f,textureWidth:Math.min(innerWidth,1280),textureHeight:Math.min(innerHeight,900),clipBias:.003});reflection.rotation.x=-Math.PI/2;reflection.position.y=-.045;scene.add(reflection);floor.position.y=-.04;floor.material.transparent=true;floor.material.opacity=.87;
 const stone=new T.MeshStandardMaterial({map,color:0x292a2b,roughness:.8,envMapIntensity:.1}),bronze=new T.MeshStandardMaterial({color:0x5e4c32,metalness:.8,roughness:.35,envMapIntensity:.45}),warm=new T.MeshStandardMaterial({color:0xe9d3ab,emissive:0xdcb776,emissiveIntensity:1.6});
 function block(w,h,d,x,y,z,material){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);mesh.receiveShadow=true;mesh.castShadow=true;scene.add(mesh);return mesh}
 block(46,9,1,0,4.5,-8,stone);block(19,.35,8,1,5,-4,stone);block(19,.025,.08,1,4.8,-.1,warm);block(19,.025,.08,1,4.8,-7,warm);
 const glazing=new T.MeshPhysicalMaterial({color:0x171d20,metalness:.35,roughness:.16,clearcoat:1,envMapIntensity:.4});
 for(const x of [-7,-2,3,8]){block(3.8,4,.06,x,2.3,-7.42,glazing);block(.045,4.6,.1,x-1.94,2.3,-7.3,bronze);block(.045,4.6,.1,x+1.94,2.3,-7.3,bronze);block(3.8,.045,.1,x,4.32,-7.3,bronze);block(.06,2.8,.06,x+1.4,2,-7.24,warm)}
 for(const x of [-8.8,10.8]){block(.8,5,.8,x,2.5,-1.4,stone);block(.025,3,.025,x+.41,2.5,-1.1,warm)}
 block(45,.12,1.3,0,.02,-6.8,stone);for(let i=-12;i<15;i++)block(.015,.001,22,i*2,-.035,2,new T.MeshStandardMaterial({color:0x060708,roughness:1}));
 for(const x of [-5,3,9]){const lamp=new T.PointLight(0xffd8a0,35,10,2);lamp.position.set(x,3.6,-5.8);scene.add(lamp)}
 const car=await loadVehicle('Sedan');scene.add(car);car.updateMatrixWorld(true);const wheelGroups=[];const components=[];car.traverse(o=>{if(!o.isMesh)return;const b=new T.Box3().setFromObject(o),s=b.getSize(new T.Vector3()),c=b.getCenter(new T.Vector3());if(s.x<1.1&&s.y<1.15&&s.z<1.15&&c.y<.8&&Math.abs(c.x)>.65&&Math.abs(c.z)>1)components.push({o,c})});for(const side of [-1,1])for(const axle of [-1,1]){const parts=components.filter(({c})=>Math.sign(c.x)===side&&Math.sign(c.z)===axle);if(!parts.length)continue;const bounds=new T.Box3();parts.forEach(({o})=>bounds.union(new T.Box3().setFromObject(o)));const pivot=new T.Group();pivot.position.copy(bounds.getCenter(new T.Vector3()));scene.add(pivot);parts.forEach(({o})=>pivot.attach(o));car.attach(pivot);wheelGroups.push(pivot)}car.rotation.y=Math.PI/2;const lights=new T.Group();car.add(lights);for(const side of [-.72,.72]){const lamp=new T.SpotLight(0xdceaff,0,18,.3,.6,1.5);lamp.position.set(side,.65,2.35);lamp.target.position.set(side,.1,12);lights.add(lamp,lamp.target)}
 const lamps=[];car.traverse(o=>{if(o.isMesh&&o.material?.name==='Headlight')lamps.push(o.material)});
 let t=4.8,start=0,running=false,raf=0;
 function compose(time){const approach=T.MathUtils.clamp((time-1.25)/2.45,0,1),travel=1-Math.pow(1-approach,2);car.position.x=-19+travel*21.5;car.position.z=0;for(const wheel of wheelGroups)wheel.rotation.x=travel*21.5/.35;const mobile=stage.clientWidth<760;camera.fov=mobile?44:34;camera.position.set(mobile?10:8,1.9,mobile?11:8.5);camera.lookAt(mobile?1:-1.4,1.15,-1);camera.updateProjectionMatrix();lights.children.forEach(o=>{if(o.isSpotLight)o.intensity=T.MathUtils.smoothstep(time,.5,1.3)*28});lamps.forEach(m=>{m.emissive.set(0xc9dfff);m.emissiveIntensity=T.MathUtils.smoothstep(time,.5,1.3)*1.8});hero.classList.toggle('entrance-playing',time<3.7);hero.style.setProperty('--arrival-dark',String(1-T.MathUtils.smoothstep(time,0,1.25)));renderer.render(scene,camera)}
 function finish(){running=false;t=4.8;compose(t);skip.hidden=true;replay.hidden=false;hero.classList.remove('entrance-playing');try{sessionStorage.setItem('martinez-arrival','seen')}catch{}}
 function tick(now){if(!running)return;t=(now-start)/1000;if(t>=4.8){finish();return}compose(t);raf=requestAnimationFrame(tick)}
 function play(){cancelAnimationFrame(raf);if(reduced.matches){finish();return}t=0;start=performance.now();running=true;skip.hidden=false;replay.hidden=true;raf=requestAnimationFrame(tick)}
 stage.classList.add('ready');hero.classList.add('arrival-ready');skip.addEventListener('click',()=>{cancelAnimationFrame(raf);finish()});replay.addEventListener('click',play);reduced.addEventListener('change',()=>{if(reduced.matches)finish()});addEventListener('resize',()=>{if(!running)compose(t)});addEventListener('pagehide',()=>{cancelAnimationFrame(raf);view.dispose()},{once:true});
 if(!reduced.matches&&!seen&&!navigator.connection?.saveData)play();else finish();
}
